import { useState } from "react";
import Button from "./Button.js";
import useAuth from "../../lib/useAuth.js";

const LoginTab = () => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const { login } = useAuth();
  const [loading, setLoading] = useState(false);

  const apiEndpoint = `${process.env.REACT_APP_API_URL}/auth/`;

  const checkLogin = async (x) => {
    x.preventDefault();
    if (username && password) {
      try {
        setLoading(true);
        const res = await fetch(apiEndpoint, {
          method: "POST",
          headers: {
            Accept: "application/json",
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ username: username, password: password }),
        });

        const status = res.status;
        if (status === 200) {
          const token = await res.json();
          login(token);
          return;
        } else if (status === 401) {
          setError("Invalid credentials");
        } else {
          throw new Error();
        }
      } catch (err) {
        setError("An error occurred. Please try again later.");
      } finally {
        setLoading(false);
      }
    } else {
      setError("Enter a username and password");
    }
  };

  return (
    <form
      className=" flex flex-col justify-between w-full bg-card rounded-lg h-[270px] text-accent-foreground"
      onSubmit={checkLogin}
      autoComplete="off"
    >
      <div className="flex flex-col justify-evenly w-full h-[85%]">
        <div className="field">
          <div>Username</div>
          <input
            type="text"
            maxLength="15"
            value={username}
            onChange={(x) => setUsername(x.target.value)}
          ></input>
        </div>
        <div className="field">
          <div>Password</div>
          <input
            type="password"
            value={password}
            onChange={(x) => setPassword(x.target.value)}
          ></input>
        </div>
        <div
          className="error"
          style={{ visibility: error ? "visible" : "hidden" }}
        >
          {error}
        </div>
      </div>
      {loading && <div className="loading"></div>}
      <Button name={"Login"} />
    </form>
  );
};

export default LoginTab;
