import { useEffect, useState, useRef, useContext } from "react";
import Games from "../lib/Games.js";
import { PlayersContext } from "../PlayersContext.js";
import { useNavigate } from "react-router-dom";
import Active from "../components/ui/Active.js";
import CallOut from "../components/ui/dialogs/CallOut.js";
import Scores from "../components/ui/dialogs/Scores.js";
import Button from "../components/ui/Button.js";

const Battle = () => {
  const {
    playercontext: [players],
    roundcontext: [round],
    benchcontext: [bench],
  } = useContext(PlayersContext);
  const [game, setGame] = useState("");
  const [a, setA] = useState();
  const [b, setB] = useState();
  const [redice, setRedice] = useState("");
  const [blueice, setBlueice] = useState("");
  const [light, setLight] = useState("");
  const lighttimer = useRef(null);
  const [show, setShow] = useState(false);
  const navigate = useNavigate();
  const mountedRef = useRef(true);

  const lighton = () => {
    if (lighttimer.current) clearTimeout(lighttimer.current);
    setLight("green");
    lighttimer.current = setTimeout(() => {
      setLight("red");
    }, Math.random() * (20000 - 10000) + 10000);
  };

  const nonbenchedPlayers = players.filter(
    (plyr) => !bench.includes(plyr.score_id)
  );

  useEffect(() => {
    if (nonbenchedPlayers.length === 0) {
      navigate("/home");
      return;
    }
    if (mountedRef.current) {
      if (nonbenchedPlayers.length) {
        //set game
        let playable = Games.filter(
          (x) => x.min_players <= nonbenchedPlayers.length
        );
        let int = Math.floor(Math.random() * playable.length);
        setGame(playable[int]);

        let inactive = [...nonbenchedPlayers];
        let activeA = [];
        let activeB = [];
        let size = 0;

        if (playable[int].c_fixed_ppl) {
          size = playable[int].min_players;
        } else {
          size =
            (1 +
              Math.floor(Math.random() * (nonbenchedPlayers.length / 2 - 1))) *
            2;
        }
        if (playable[int].c_call_out) {
          let min = Math.min(...inactive.map((x) => x.player_score));
          let low = inactive.filter((x) => x.player_score === min);

          if (nonbenchedPlayers.some((x) => x.priority === true)) {
            let r = nonbenchedPlayers.findIndex((x) => x.priority === true);
            activeA.push(inactive[r].score_id);
            delete nonbenchedPlayers[r].priority;
          } else {
            let r = Math.floor(Math.random() * low.length);
            activeA.push(
              inactive.filter((x) => x.player_score === min)[r].score_id
            );
          }
        } else {
          let decider = 1;
          for (let i = 0; i < size; i++) {
            let r = nonbenchedPlayers.some((x) => x.priority === true)
              ? nonbenchedPlayers.findIndex((x) => x.priority === true)
              : Math.floor(Math.random() * inactive.length);
            delete nonbenchedPlayers[r].priority;
            if (decider > 0) {
              activeA.push(inactive[r].score_id);
            } else {
              activeB.push(inactive[r].score_id);
            }
            inactive.splice(r, 1);
            decider = decider * -1;
          }
        }

        setA(activeA);

        if (playable[int].c_light) {
          setB(activeB);
        } else if (playable[int].c_call_out) {
          setShow(true);
        } else {
          setB(activeB);
        }
      }
    }
    return () => {
      mountedRef.current = false;
      if (lighttimer.current) clearTimeout(lighttimer.current);
    };
  }, []);

  const chooseB = (x) => {
    setB([x]);
    setShow(false);
  };

  return (
    <div className="flex flex-col h-full justify-between">
      <div className="w-full bg-secondary-foreground text-secondary rounded-md text-center text-[20px] p-2 font-bold">
        {nonbenchedPlayers.length
          ? `Round ${round + 1}: ${game.title}`
          : "Battle"}
      </div>

      <div className="flex flex-col items-center justify-evenly h-full w-full">
        {game.c_call_out ? (
          <div className="flex gap-2 h-1/2 w-full items-center justify-between">
            <Active ids={a} opp={b} className="bg-red-700"></Active>
            <Active ids={b} opp={a} className="bg-blue-800"></Active>
          </div>
        ) : game.id ? (
          <div className="flex gap-2 h-1/2 w-full items-center justify-between">
            <Active ids={a} className="bg-red-700"></Active>
            <Active ids={b} className="bg-blue-800"></Active>
          </div>
        ) : (
          <div className="flex gap-2 h-1/2 w-full items-center justify-between">
            <Active
              ids={a}
              className="bg-red-700"
              handleWord={setBlueice}
              icelevel={blueice}
            ></Active>
            <Active
              ids={b}
              className="bg-blue-800"
              handleWord={setRedice}
              icelevel={redice}
            ></Active>
          </div>
        )}

        <div className="bg-accent text-accent-foreground rounded-md w-full font-bold p-4 h-1/3 flex items-center">
          {game.description}
        </div>

        <div className="rounded-md flex items-center gap-2 h-16 w-full justify-center">
          <div
            className="h-full flex-grow rounded-md flex"
            style={{ backgroundColor: light }}
          >
            <div className="text-red-700 text-[30px] font-bold h-full w-1/2 flex justify-center items-center">
              {redice}
            </div>
            <div className="text-blue-700 text-[30px] font-bold h-full w-1/2 flex justify-center items-center">
              {blueice}
            </div>
          </div>

          {game.c_light ? (
            <Button
              name="Go"
              onClick={() => lighton()}
              className={`${light == "green" ? "invisible" : "visible"} !w-1/4`}
            />
          ) : (
            <CallOut
              show={show}
              onHide={() => {
                setShow(false);
                navigate("/home");
              }}
              id={a}
              chooseB={chooseB}
            />
          )}
        </div>
      </div>
      <div className="flex justify-end w-full">
        <Scores />
      </div>
    </div>
  );
};

export default Battle;
