import Breadcrumbs from "./components/ui/Breadcrumbs";
import Menu from "./components/ui/Menu";
import { Outlet } from "react-router-dom";

export default function Layout() {
  return (
    <div className="flex justify-center w-full h-full bg-[rgb(155,193,235)]">
      <div className="home">
        <div className="flex w-screen max-w-[480px] h-12 items-center justify-between p-2 bg-accent-foreground text-accent">
          <Breadcrumbs />
          <Menu />
        </div>
        <main className="w-full flex-1 pt-2">
          <Outlet />
        </main>
      </div>
    </div>
  );
}
