import { useContext } from "react";
import { PlayersContext } from "../../../PlayersContext";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "../dialog";
import { sorter } from "../../../lib/utils";

const CallOut = ({ show, onHide, id, chooseB }) => {
  const {
    playercontext: [players],
    benchcontext: [bench],
  } = useContext(PlayersContext);

  let nonbenchedPlayers = players
    .slice()
    .filter((plyr) => !bench.includes(plyr.score_id));

  if (!show) return null;
  return (
    <Dialog open={show} onOpenChange={onHide}>
      <DialogContent aria-describedby={undefined}>
        <DialogHeader>
          <DialogTitle>
            {nonbenchedPlayers.find((user) => user.score_id == id).player_name}{" "}
            calls out
          </DialogTitle>
        </DialogHeader>
        <div id="players">
          {nonbenchedPlayers
            .filter((user) => user.score_id != id)
            .slice()
            .sort(sorter)
            .map((x) => {
              return (
                <div
                  key={x.score_id}
                  className="cursor-pointer flex gap-1 items-center justify-between w-full bg-accent text-accent-foreground p-1 border"
                  onClick={() => chooseB(x.score_id)}
                >
                  <div className="truncate">{x.player_name}</div>
                  <div>{x.player_score}</div>
                </div>
              );
            })}
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default CallOut;
