import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogDescription,
} from "../dialog";
import { CircleQuestionMark } from "lucide-react";

const Rules = () => {
  return (
    <Dialog>
      <DialogTrigger asChild>
        <CircleQuestionMark className="rounded-md text-primary-foreground cursor-pointer" />
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Welcome to Ice Breakerz!</DialogTitle>
          <DialogDescription>
            <span>
              Designate someone to handle the app and add as many players as you
              like to start. Each round's mini game will be randomly chosen, as
              well as the players who participate. Follow the instructions
              written! Everyone who isn't battling will vote for the mini game
              winner. Keep playing until someone reaches 10 points (or however
              long you want). Have fun!
            </span>
            <br />
            <br />
            <span>
              <li>
                Depending on the game, you might need to react quickly, call out
                opponents, or complete challenges.
              </li>
              <li>
                Winners are assigned after each round and will get a point.
              </li>
              <li>
                Call outs allow the player with the lowest score to choose an
                opponent to challenge. The loser of the round will also lose a
                point.
              </li>
              <li>
                The game continues round-by-round, updating scores until players
                decide to stop.
              </li>
              <li>Tap a player's name to manually adjust their score.</li>
            </span>
          </DialogDescription>
        </DialogHeader>
      </DialogContent>
    </Dialog>
  );
};

export default Rules;
