import { useState, useContext, useEffect, useRef } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "../dialog";
import { PlayersContext } from "../../../PlayersContext";
import { useNavigate } from "react-router-dom";
import Button from "../Button";
import { X } from "lucide-react";

const PlayerScore = ({
  name,
  score,
  id,
  submitScore,
  isManagingBench,
  manageBench,
  rm,
  benched = false,
}) => {
  const [show, setShow] = useState(false);

  const {
    playercontext: [players, setPlayers],
  } = useContext(PlayersContext);
  const navigate = useNavigate();
  const prevShowRef = useRef(show);
  const changeRef = useRef(false);

  const playerIndex = players.findIndex((user) => user.score_id === id);
  const player = players[playerIndex];

  const playFirst = () => {
    player.priority = true;
    if (changeRef.current) {
      submitScore(id);
      changeRef.current = false;
    }
    navigate("/battle");
  };

  useEffect(() => {
    if (prevShowRef.current === true && !show && changeRef.current) {
      submitScore(id);
      changeRef.current = false;
    }
    prevShowRef.current = show;
  }, [show]);

  const updateScore = (add) => {
    if (add) {
      player.player_score++;
    } else {
      player.player_score--;
    }
    setPlayers([...players]);
    if (!changeRef.current) {
      changeRef.current = true;
    }
  };

  return (
    <Dialog open={show} onOpenChange={setShow}>
      <DialogTrigger asChild>
        <div
          onClick={() => (isManagingBench ? manageBench(id) : setShow(true))}
          className="cursor-pointer bg-accent text-accent-foreground text-sm flex h-full w-full items-center justify-between border"
        >
          <div className="flex flex-grow overflow-hidden items-center justify-between">
            <div className="truncate px-2 max-w-[75%]">{name}</div>
            <div className="text-[12px] text-[rgb(155,204,223)] w-8 text-right px-2 flex-none">
              {score}
            </div>
          </div>
          <X
            className="h-8 w-8 flex-none"
            onClick={(e) => {
              if (!isManagingBench) {
                e.stopPropagation();
                rm(id);
              }
            }}
          />
        </div>
      </DialogTrigger>
      <DialogContent aria-describedby={undefined}>
        <DialogHeader>
          <DialogTitle>{player.player_name}</DialogTitle>
        </DialogHeader>
        <div className="flex justify-between items-center">
          <Button
            className="!w-16"
            onClick={() => updateScore(false)}
            name="-"
          />
          {player.player_score}
          <Button
            className="!w-16"
            onClick={() => updateScore(true)}
            name="+"
          />
        </div>
        {!benched && <Button name="Challenge" onClick={playFirst} />}
      </DialogContent>
    </Dialog>
  );
};

export default PlayerScore;
