import { useState, useEffect } from "react";
import Button from "../Button.js";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "../dialog.jsx";
import { UserRoundPlus } from "lucide-react";

const AddEntry = ({ postEntry, list, value }) => {
  const [show, setShow] = useState(false);
  const [search, setSearch] = useState("");
  const [error, setError] = useState("");

  useEffect(() => {
    setSearch("");
    setError("");
  }, [show]);

  const submitEntry = (x) => {
    x.preventDefault();
    const trimmed = search.replace(/\s{2,}/g, " ").trim();

    if (!trimmed) {
      setError(`Enter a ${value}.`);
    } else {
      if (
        list.some(
          (entry) =>
            (value === "Lobby" ? entry.lobby_name : entry.player_name) ===
            trimmed
        )
      ) {
        setError(`${value + " " + search} already exists. Enter another name.`);
      } else {
        postEntry(trimmed);
        setShow(false);
      }
    }
  };

  return (
    <Dialog open={show} onOpenChange={setShow}>
      <DialogTrigger asChild>
        {value === "Lobby" ? (
          <Button name={`Add ${value}`}></Button>
        ) : (
          <div className="flex justify-center w-full bg-accent-foreground rounded-md h-10 text-accent py-2 cursor-pointer">
            <UserRoundPlus className="py-1 pr-1" />
            <div>Add</div>
          </div>
        )}
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Enter a {value}</DialogTitle>
          <DialogDescription />
        </DialogHeader>
        <form
          className="flex flex-col justify-evenly h-32"
          onSubmit={submitEntry}
        >
          <input
            type="text"
            maxLength="15"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            autoFocus
          ></input>
          <div
            className="error"
            style={{ visibility: error ? "visible" : "hidden" }}
          >
            {error}
          </div>

          <Button name="Add" />
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default AddEntry;
