import { clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs) {
  return twMerge(clsx(...inputs));
}

export const isAuthorized = () => {
  const expiration = sessionStorage.getItem("expiresAt");
  if (expiration) {
    const expiresIn = new Date(JSON.parse(expiration)).getTime() - Date.now();
    if (expiresIn > 0) {
      return true;
    } else {
      sessionStorage.removeItem("token");
      sessionStorage.removeItem("expiresAt");
    }
  }
  return false;
};

export const sorter = (x, y) => {
  if (x.player_score < y.player_score) {
    return 1;
  } else if (x.player_score > y.player_score) {
    return -1;
  }
  return 0;
};
