import React from "react";
const Button = React.forwardRef(({ name, onClick, className }, ref) => {
  return (
    <button
      className={`w-full bg-accent-foreground text-accent rounded-md h-10 ${className}`}
      onClick={onClick}
      ref={ref}
    >
      {name}
    </button>
  );
});
export default Button;
