import { useContext } from "react";
import { PlayersContext } from "../../../PlayersContext";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "../dialog";
import { List } from "lucide-react";
import { sorter } from "../../../lib/utils";

const Scores = () => {
  const {
    playercontext: [players],
    benchcontext: [bench],
  } = useContext(PlayersContext);

  return (
    <Dialog>
      <DialogTrigger asChild>
        <List className="h-full rounded-md p-2 bg-accent-foreground text-accent w-10 cursor-pointer" />
      </DialogTrigger>
      <DialogContent aria-describedby={undefined}>
        <DialogHeader>
          <DialogTitle>Scores</DialogTitle>
        </DialogHeader>
        <div id="players">
          {players
            .filter((plyr) => !bench.includes(plyr.score_id))
            .sort(sorter)
            .map((x) => {
              return (
                <div
                  key={x.score_id}
                  className="flex items-center gap-1 justify-between w-full bg-accent text-accent-foreground p-1 border"
                >
                  <div className="truncate">{x.player_name}</div>
                  <div>{x.player_score}</div>
                </div>
              );
            })}
          {players
            .filter((plyr) => bench.includes(plyr.score_id))
            .sort(sorter)
            .map((x) => {
              return (
                <div
                  key={x.score_id}
                  className="flex items-center gap-1 justify-between w-full bg-secondary text-secondary-foreground p-1 border"
                >
                  <div className="truncate">{x.player_name}</div>
                  <div>{x.player_score}</div>
                </div>
              );
            })}
        </div>
      </DialogContent>
    </Dialog>
  );
};

export default Scores;
