import LoginTab from "../components/ui/LoginTab.js";
import SignupTab from "../components/ui/SignupTab.js";
import Button from "../components/ui/Button.js";
import { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "../components/ui/tabs.jsx";
import { isAuthorized } from "../lib/utils.js";

const Login = () => {
  const navigate = useNavigate();
  useEffect(() => {
    if (isAuthorized()) {
      navigate("/lobbies");
    }
  }, []);
  return (
    <div className="flex justify-center w-full h-full bg-[rgb(155,193,235)]">
      <div className="home">
        <div className="logo" />
        <div className="w-full gap-4 m-auto flex flex-col justify-evenly items-center border rounded-md shadow-md bg-card p-3">
          <div className="flex w-full flex-col ">
            <Tabs defaultValue="login">
              <TabsList className="bg-card w-full">
                <TabsTrigger value="login">Log In</TabsTrigger>
                <TabsTrigger value="signup">Sign Up</TabsTrigger>
              </TabsList>
              <TabsContent value="login">
                <LoginTab />
              </TabsContent>
              <TabsContent value="signup">
                <SignupTab />
              </TabsContent>
            </Tabs>
          </div>
          <Button
            name="Continue as Guest"
            onClick={() => navigate("/home")}
            className="!bg-accent !text-accent-foreground"
          />
        </div>
      </div>
    </div>
  );
};

export default Login;
