import { useState } from "react";
import useAuth from "../../lib/useAuth";
import Button from "./Button";

const SignupTab = () => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [password2, setPassword2] = useState("");
  const [error, setError] = useState("");
  const { login } = useAuth();
  const [loading, setLoading] = useState(false);

  const apiEndpoint = `${process.env.REACT_APP_API_URL}/users/`;

  const handleSubmit = async (x) => {
    x.preventDefault();
    if (!username.trim()) {
      setError("Enter a username");
    } else if (!password) {
      setError("Enter a password");
    } else if (password !== password2) {
      setError("Passwords do not match");
    } else {
      try {
        setLoading(true);
        const res = await fetch(apiEndpoint, {
          method: "POST",
          headers: {
            Accept: "application/json",
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ username: username, password: password }),
        });
        const resStatus = res.status;
        if (resStatus === 409) {
          setError("Username already exists");
        } else if (resStatus === 201) {
          const auth = await fetch(`${process.env.REACT_APP_API_URL}/auth/`, {
            method: "POST",
            headers: {
              Accept: "application/json",
              "Content-Type": "application/json",
            },
            body: JSON.stringify({ username: username, password: password }),
          });
          const authResStatus = auth.status;
          if (authResStatus == 200) {
            const token = await auth.json();
            login(token);
            return;
          } else {
            throw new Error("Login failed after signup.");
          }
        } else {
          throw new Error("Server down.");
        }
      } catch (err) {
        setError("An error occured. Please try again later.");
      } finally {
        setLoading(false);
      }
    }
  };

  return (
    <form
      className=" flex flex-col justify-between w-full bg-card rounded-lg h-[270px] text-accent-foreground"
      onSubmit={handleSubmit}
      autoComplete="off"
    >
      <div className="flex flex-col justify-evenly w-full h-[85%]">
        <div>
          <div>Username</div>
          <input
            type="text"
            maxLength="15"
            value={username}
            onChange={(x) => setUsername(x.target.value)}
          ></input>
        </div>
        <div className="field">
          <div>Password</div>
          <input
            type="password"
            minLength="8"
            value={password}
            onChange={(x) => setPassword(x.target.value)}
          ></input>
        </div>
        <div className="field">
          <div>Confirm Password</div>
          <input
            type="password"
            minLength="8"
            value={password2}
            onChange={(x) => setPassword2(x.target.value)}
          ></input>
        </div>
        <div
          className="error"
          style={{ visibility: error ? "visible" : "hidden" }}
        >
          {error}
        </div>
      </div>
      {loading && <div className="loading"></div>}
      <Button name="Sign up" />
    </form>
  );
};
export default SignupTab;
