import { useLocation, Link } from "react-router-dom";
import React from "react";
import {
  Breadcrumb,
  BreadcrumbList,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "./breadcrumb";
import { PlayersContext } from "../../PlayersContext";
import { useContext } from "react";

export default function Breadcrumbs() {
  const location = useLocation();
  const currentPath = location.pathname;
  const {
    lobbycontext: [lobby],
  } = useContext(PlayersContext);
  const routes = [
    { path: "/lobbies", label: "Lobbies" },
    { path: "/home", label: lobby ? lobby.name : "Guest" },
    { path: "/battle", label: "Battle" },
  ];
  const currentRouteIndex = routes.findIndex(
    (route) => route.path === currentPath
  );
  return (
    <Breadcrumb className=" h-full w-full">
      <BreadcrumbList className=" h-full">
        {routes.slice(lobby ? 0 : 1, currentRouteIndex).map((route) => (
          <React.Fragment key={route.path}>
            <BreadcrumbItem>
              <BreadcrumbLink asChild>
                <Link className="w-14 truncate text-center" to={route.path}>
                  {route.label}
                </Link>
              </BreadcrumbLink>
            </BreadcrumbItem>
            <BreadcrumbSeparator />
          </React.Fragment>
        ))}
        <BreadcrumbItem className=" h-full">
          <BreadcrumbPage className="flex items-center justify-center p-2 min-w-14 rounded-md text-accent-foreground bg-accent h-full">
            {routes[currentRouteIndex].label}
          </BreadcrumbPage>
        </BreadcrumbItem>
      </BreadcrumbList>
    </Breadcrumb>
  );
}
