import { useContext, useState, useEffect } from "react";
import { PlayersContext } from "../PlayersContext";
import { useNavigate } from "react-router-dom";
import Lobby from "../components/ui/Lobby.js";
import { isAuthorized } from "../lib/utils.js";
import AddEntry from "../components/ui/dialogs/AddEntry.js";

const Lobbies = () => {
  const {
    playercontext: [, setPlayers],
    lobbycontext: [, setLobby],
    roundcontext: [, setRound],
    benchcontext: [, setBench],
  } = useContext(PlayersContext);
  const [lobbies, setLobbies] = useState([]);
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const apiEndpoint = `${process.env.REACT_APP_API_URL}/lobbies/`;
  const token = sessionStorage.getItem("token");

  useEffect(() => {
    if (isAuthorized()) {
      const getdata = async () => {
        setLoading(true);
        try {
          const res = await fetch(apiEndpoint, {
            headers: { Authorization: token },
          });
          if (!res.ok) {
            throw new Error(res.statusText);
          }
          const data = await res.json();
          setLobbies(data.lobbies);
        } catch (err) {
          console.log("error");
          console.log(err.message);
          navigate("/");
        }
        setLoading(false);
      };
      getdata();
    } else {
      navigate("/");
    }
  }, []);

  const postLobby = async (name) => {
    setLoading(true);
    const res = await fetch(apiEndpoint, {
      method: "POST",
      headers: {
        Accept: "application/json",
        "Content-Type": "application/json",
        Authorization: token,
      },
      body: JSON.stringify({ lobby_name: name }),
    });
    const data = await res.json();
    setLoading(false);
    setLobbies([...lobbies, data.newLobby]);
  };

  const loadLobby = async (id, lobby_round, lobby_name) => {
    const scores = `${process.env.REACT_APP_API_URL}/scores/`;
    try {
      setLoading(true);
      const res = await fetch(scores + id, {
        headers: {
          Authorization: token,
        },
      });
      if (!res.ok) {
        throw new Error(res.statusText);
      }
      const data = await res.json();

      setLobby({ id: id, name: lobby_name });
      setRound(lobby_round);
      setPlayers(data);
      setBench([]);
      navigate("/home");
    } catch (err) {
      console.log(err.message);
      navigate("/");
    }
  };

  const removeLobby = async (id) => {
    setLoading(true);
    setLobbies(lobbies.filter((lobby) => lobby.lobby_id !== id));
    await fetch(apiEndpoint + id, {
      method: "DELETE",
      headers: {
        Authorization: token,
      },
    });
    setLoading(false);
  };

  return (
    <div className="h-full flex flex-col gap-2">
      <div id="players" className="p-2 rounded-md border bg-card">
        {!!lobbies.length &&
          lobbies.map((x) => {
            return (
              <Lobby
                key={x.lobby_id}
                name={x.lobby_name}
                id={x.lobby_id}
                rm={removeLobby}
                round={x.lobby_round}
                players={x.players}
                load={loadLobby}
              />
            );
          })}
        {!loading && !lobbies.length && (
          <div className="w-3/4 m-auto text-center text-sm rounded-md p-2 bg-accent text-accent-foreground">
            Add a lobby to get started.
          </div>
        )}
      </div>
      <div>
        <AddEntry postEntry={postLobby} list={lobbies} value="Lobby" />
      </div>
      {loading && <div className="loading"></div>}
    </div>
  );
};

export default Lobbies;
