import { useState, useContext, useEffect } from "react";
import { PlayersContext } from "../PlayersContext.js";
import { useNavigate } from "react-router-dom";
import { isAuthorized, sorter } from "../lib/utils.js";
import PlayerScore from "../components/ui/dialogs/PlayerScore.js";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "../components/ui/tabs";
import { Swords, Ban } from "lucide-react";
import AddEntry from "../components/ui/dialogs/AddEntry.js";
import Reset from "../components/ui/dialogs/Reset.js";

const Home = () => {
  const {
    playercontext: [players, setPlayers],
    roundcontext: [round, setRound],
    lobbycontext: [lobby],
    benchcontext: [bench, setBench],
  } = useContext(PlayersContext);
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [isManagingBench, setManagingBench] = useState(false);
  const apiEndpoint = `${process.env.REACT_APP_API_URL}/scores/`;
  const token = sessionStorage.getItem("token");

  useEffect(() => {
    if (!isAuthorized()) {
      let tmp = sessionStorage.getItem("sessionplayers");
      let tmpround = sessionStorage.getItem("round");
      if (tmp) {
        setPlayers(JSON.parse(tmp));
        setRound(Number(tmpround));
      }
    } else {
      if (!lobby) {
        navigate("/lobbies");
      }
    }
  }, []);

  const removePlayer = async (id) => {
    setPlayers(players.filter((user) => user.score_id !== id));
    if (isAuthorized()) {
      setLoading(true);
      await fetch(apiEndpoint + id, {
        method: "DELETE",
        headers: {
          Authorization: token,
        },
      });
      setLoading(false);
    } else {
      sessionStorage.setItem(
        "sessionplayers",
        JSON.stringify(players.filter((user) => user.score_id !== id))
      );
    }
  };

  const postPlayer = async (name) => {
    let data;
    if (isAuthorized()) {
      setLoading(true);
      const res = await fetch(apiEndpoint, {
        method: "POST",
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
          Authorization: token,
        },
        body: JSON.stringify({ player_name: name, lobby_id: lobby.id }),
      });
      const json = await res.json();
      const newPlayer = json.newPlayer;
      data = [...players, newPlayer];
      setLoading(false);
    } else {
      const ids = new Date();
      data = players.concat([
        { player_name: name, player_score: 0, score_id: ids.getTime() },
      ]);
      sessionStorage.setItem("sessionplayers", JSON.stringify(data));
    }
    setPlayers(data);
  };

  const submitScore = async (id) => {
    if (isAuthorized()) {
      setLoading(true);
      await fetch(apiEndpoint + id, {
        method: "PUT",
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
          Authorization: token,
        },
        body: JSON.stringify({
          player_score: players.find((user) => user.score_id === id)
            .player_score,
        }),
      });
      setLoading(false);
    } else {
      sessionStorage.setItem("sessionplayers", JSON.stringify(players));
    }
  };

  const manageBench = (id) => {
    setBench((prev) =>
      prev.includes(id)
        ? prev.filter((playerId) => playerId !== id)
        : [...prev, id]
    );
  };

  const resetScores = async (x) => {
    if (players.length) {
      const resetPlayers = players.map((user) => ({
        ...user,
        player_score: 0,
      }));

      setPlayers(resetPlayers);
      setRound(0);
      if (isAuthorized()) {
        setLoading(true);
        await fetch(apiEndpoint + `?lobbyId=${lobby.id}`, {
          method: "PUT",
          headers: {
            Accept: "application/json",
            "Content-Type": "application/json",
            Authorization: token,
          },
          body: JSON.stringify({
            player_score: 0,
          }),
        });
        await fetch(`${process.env.REACT_APP_API_URL}/lobbies/` + lobby.id, {
          method: "PUT",
          headers: {
            Accept: "application/json",
            "Content-Type": "application/json",
            Authorization: token,
          },
          body: JSON.stringify({
            lobby_round: 0,
          }),
        });
        setLoading(false);
      } else {
        sessionStorage.setItem("sessionplayers", JSON.stringify(resetPlayers));
        sessionStorage.setItem("round", 0);
      }
    }
  };

  return (
    <div className="h-full flex flex-col gap-2">
      <Tabs defaultValue="active" className="h-full">
        <TabsList className="bg-card w-full">
          <TabsTrigger value="active">Players</TabsTrigger>
          <div className="w-24 text-center p-1 text-accent-foreground font-bold">
            Round {round}
          </div>
          <TabsTrigger value="bench">Bench</TabsTrigger>
        </TabsList>
        <TabsContent value="active">
          <div id="players" className="p-2 rounded-md border bg-card">
            {!players.length && (
              <div className="w-3/4 m-auto text-center text-sm rounded-md p-1 bg-accent text-accent-foreground">
                Add players to battle.
              </div>
            )}
            {!!players.length &&
              players
                .slice()
                .filter((plyr) => !bench.includes(plyr.score_id))
                .sort(sorter)
                .map((x) => {
                  return (
                    <PlayerScore
                      key={x.score_id}
                      name={x.player_name}
                      score={x.player_score}
                      id={x.score_id}
                      submitScore={submitScore}
                      rm={removePlayer}
                      isManagingBench={isManagingBench}
                      manageBench={manageBench}
                    ></PlayerScore>
                  );
                })}
          </div>
        </TabsContent>
        <TabsContent value="bench">
          <div id="players" className="p-2 rounded-md border bg-card">
            {!bench.length && (
              <div className="w-3/4 m-auto text-center text-sm rounded-md p-1 bg-accent text-accent-foreground">
                Benched players will not participate.
              </div>
            )}
            {!!bench.length &&
              players
                .slice()
                .filter((plyr) => bench.includes(plyr.score_id))
                .sort(sorter)
                .map((x) => {
                  return (
                    <PlayerScore
                      key={x.score_id}
                      name={x.player_name}
                      score={x.player_score}
                      id={x.score_id}
                      submitScore={submitScore}
                      isManagingBench={isManagingBench}
                      rm={removePlayer}
                      manageBench={manageBench}
                      benched={true}
                    ></PlayerScore>
                  );
                })}
          </div>
        </TabsContent>
      </Tabs>

      {loading && <div className="loading"></div>}
      <div className="flex w-full items-center justify-evenly gap-2">
        <AddEntry postEntry={postPlayer} list={players} value="Player" />
        <div
          onClick={
            isManagingBench
              ? () => setManagingBench(false)
              : () => setManagingBench(true)
          }
          className={`flex justify-center w-full rounded-md h-10 py-2 transition duration-150 cursor-pointer ${
            isManagingBench
              ? "bg-accent text-accent-foreground ring-2 ring-accent-foreground "
              : "bg-accent-foreground text-accent "
          }`}
        >
          <Ban className="py-1 pr-1" />
          <div>Bench</div>
        </div>
        <Reset reset={resetScores} />
        <div
          onClick={() => {
            if (players.length - bench.length > 1) navigate("/battle");
          }}
          className={`flex justify-center w-full bg-accent-foreground rounded-md h-10 text-accent py-2 ${
            players.length - bench.length > 1
              ? "cursor-pointer"
              : "cursor-not-allowed opacity-70"
          }`}
        >
          <Swords className="py-1 pr-1" />
          <div>Battle</div>
        </div>
      </div>
    </div>
  );
};

export default Home;
