import { X } from "lucide-react";

const Lobby = ({ name, id, load, rm, round, players }) => {
  return (
    <div
      onClick={() => load(id, round, name)}
      className="cursor-pointer bg-accent text-accent-foreground h-full flex w-full items-center border justify-between"
    >
      <div className="flex flex-grow overflow-hidden items-center justify-between">
        <div className="truncate px-2 max-w-[50%]">{name}</div>
        <div className="text-[11px] text-[rgb(155,204,223)] flex flex-col flex-none w-[70px] px-1">
          <div>Players: {players}</div>
          <div>Rounds: {round}</div>
        </div>
      </div>
      <X
        className="h-8 w-8 flex-none"
        onClick={(e) => {
          e.stopPropagation();
          rm(id);
        }}
      />
    </div>
  );
};

export default Lobby;
