import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "../dialog.jsx";
import { useState } from "react";
import { RotateCw } from "lucide-react";
import Button from "../Button.js";

const Reset = ({ reset }) => {
  const [show, setShow] = useState(false);

  return (
    <Dialog open={show} onOpenChange={setShow}>
      <DialogTrigger asChild>
        <div className="flex justify-center w-full bg-accent-foreground rounded-md h-10 text-accent py-2 cursor-pointer">
          <RotateCw className="py-1 pr-1" />
          <div>Reset</div>
        </div>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Reset Scores?</DialogTitle>
          <DialogDescription>
            This will set all players to 0 and reset the Rounds. This cannot be
            undone.
          </DialogDescription>
        </DialogHeader>
        <Button
          name="Reset"
          onClick={() => {
            reset();
            setShow(false);
          }}
        />
      </DialogContent>
    </Dialog>
  );
};

export default Reset;
