import { useContext } from "react";
import { PlayersContext } from "../../PlayersContext.js";
import { useNavigate } from "react-router-dom";
import { isAuthorized } from "../../lib/utils.js";

const Active = ({ ids, handleWord, icelevel = "ignore", opp, className }) => {
  const {
    playercontext: [players, setPlayers],
    roundcontext: [round, setRound],
    lobbycontext: [lobby],
  } = useContext(PlayersContext);
  const navigate = useNavigate();
  const apiEndpoint = `${process.env.REACT_APP_API_URL}/scores/`;
  const token = sessionStorage.getItem("token");

  const ice = "ICE";
  const side = ids
    ? ids
        .map((x) => players.find((user) => user.score_id == x).player_name)
        .join("\n")
    : null;

  const postRound = async () => {
    await fetch(`${process.env.REACT_APP_API_URL}/lobbies/` + lobby.id, {
      method: "PUT",
      headers: {
        Accept: "application/json",
        "Content-Type": "application/json",
        Authorization: token,
      },
      body: JSON.stringify({
        lobby_round: round + 1,
      }),
    });
  };

  const postScore = async (id, increment) => {
    let playerIndex = players.findIndex((user) => user.score_id === id);
    players[playerIndex].player_score += increment;
    if (isAuthorized()) {
      await fetch(apiEndpoint + id, {
        method: "PUT",
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
          Authorization: token,
        },
        body: JSON.stringify({
          player_score: players[playerIndex].player_score,
        }),
      });
    }
  };

  const submitScore = () => {
    setPlayers([...players]);
    setRound(round + 1);
    if (!isAuthorized()) {
      sessionStorage.setItem("sessionplayers", JSON.stringify(players));
      sessionStorage.setItem("round", round + 1);
    } else {
      postRound();
    }
    navigate("/home");
  };

  const handleScore = async (x) => {
    if (opp) {
      await Promise.all([
        ...ids.map(async (id) => postScore(id, 1)),
        postScore(opp[0], -1),
      ]);
      submitScore();
    } else if (icelevel.length < ice.length - 1) {
      handleWord(ice.slice(0, icelevel.length + 1));
    } else {
      await Promise.all(ids.map(async (id) => postScore(id, 1)));
      submitScore();
    }
  };

  return (
    <div
      className={`w-1/2 ${className} text-accent h-full rounded-md p-2 text-center flex items-center justify-center`}
      onClick={handleScore}
    >
      <span className="whitespace-pre-wrap overflow-x-hidden max-h-full w-full text-sm text-ellipsis">
        {side}
      </span>
    </div>
  );
};

export default Active;
