import { useNavigate } from "react-router-dom";
import useAuth from "../../lib/useAuth";
import { LogOut, LogIn } from "lucide-react";
import { isAuthorized } from "../../lib/utils";
import Rules from "./dialogs/Rules";

const Menu = () => {
  const navigate = useNavigate();
  const { logout } = useAuth();

  return (
    <div className="flex h-full w-44  items-center justify-center gap-2">
      <Rules />
      {isAuthorized() ? (
        <div
          className="h-full flex items-center justify-center p-1 rounded-md bg-primary cursor-pointer"
          onClick={logout}
        >
          <LogOut className="h-full p-1" />
          <span className="text-sm p-1">Logout</span>
        </div>
      ) : (
        <div
          className="h-full flex items-center justify-center p-1 rounded-md bg-primary cursor-pointer"
          onClick={() => {
            navigate("/");
          }}
        >
          <LogIn className="h-full p-1" />
          <span className="text-sm p-1">Login</span>
        </div>
      )}
    </div>
  );
};

export default Menu;
